insert or ignore into base_blends (id, code, name, description, public_ingredients, benefits, mood_slugs, color) values ('base-16', '⑯ブレンド', 'Feminine Balance', 'ホルモンバランス調整・女性特有の悩みをテーマにしたベースブレンド。公開画面では配合比率を表示しません。', '["クラリセージ","パルマローザ","ラベンダー"]', '["ホルモンバランス調整","女性特有の悩み"]', '["relax","happy"]', '#d9b4a8'); insert or ignore into base_blends (id, code, name, description, public_ingredients, benefits, mood_slugs, color) values ('base-17', '⑰ブレンド', 'Woman Care', '女性の健康・美容・自信向上をテーマにしたベースブレンド。公開画面では配合比率を表示しません。', '["ゼラニウム","イランイラン","スイートオレンジ"]', '["女性の健康","美容","自信向上"]', '["happy","relax"]', '#e7b8c4'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-lavender', 'lavender', 'ラベンダー', 'Lavandula angustifolia', 'シソ科', 'ミドル', 'フローラル、ハーバル、やや甘い', 'やわらかく親しみやすい香り。夜のリラックスタイムや落ち着きたい場面でよく選ばれます。', '["就寝前の芳香浴","緊張をゆるめたい時間","フローラル系ブレンドの中心"]', '["relax","sleep"]', '["スイートオレンジ","ベルガモット","フランキンセンス","ゼラニウム"]', '一般的には扱いやすい精油ですが、肌に使う場合は希釈し、違和感があれば中止してください。', '#c7b5df'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-sweet-orange', 'sweet-orange', 'スイートオレンジ', 'Citrus sinensis', 'ミカン科', 'トップ', '甘い柑橘、明るい、親しみやすい', '明るく丸みのある柑橘の香り。気分を軽くしたい時や、ブレンドをやさしくまとめたい時に便利です。', '["朝の芳香浴","気分転換","フローラルやハーブの角を丸める"]', '["energy","happy","refresh"]', '["ラベンダー","ゼラニウム","シダーウッド","クローブ"]', '柑橘精油は種類や抽出方法で光毒性の扱いが変わります。肌使用時は製品情報を確認してください。', '#f4c97c'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-bergamot', 'bergamot', 'ベルガモット', 'Citrus bergamia', 'ミカン科', 'トップ', '上品な柑橘、ほろ苦い、紅茶のよう', '柑橘の軽さと大人っぽい苦みがある香り。リラックス系にも前向きな気分づくりにも合わせやすい精油です。', '["夕方の切り替え","落ち着いた柑橘ブレンド","上品な香りづくり"]', '["relax","happy","sleep"]', '["ラベンダー","クラリセージ","フランキンセンス","イランイラン"]', 'ベルガモットなど一部柑橘精油は光毒性に注意が必要です。肌使用後の紫外線曝露は避けてください。', '#e6c77e'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-frankincense', 'frankincense', 'フランキンセンス', 'Boswellia carterii', 'カンラン科', 'ベース', '樹脂、静か、ほのかにスパイシー', '深呼吸したくなるような樹脂の香り。静かな時間や瞑想的なブレンドに奥行きを出します。', '["夜のリラックス","呼吸を整えたい時間","香りに余韻を出す"]', '["relax","sleep"]', '["ラベンダー","ベルガモット","サンダルウッド","ミルラ"]', '樹脂系は重く残りやすいため、少量から調整してください。', '#d0b894'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-peppermint', 'peppermint', 'ペパーミント', 'Mentha piperita', 'シソ科', 'トップ', '清涼感、ミント、シャープ', 'すっきりとした清涼感のある香り。朝や作業前の切り替えに少量使うと印象が引き締まります。', '["集中したい時","リフレッシュ","重い香りの引き締め"]', '["focus","refresh"]', '["レモン","ローズマリー","ユーカリ","ラベンダー"]', '刺激を感じやすい精油です。子どもや妊娠中、持病がある場合の使用は専門家に確認してください。', '#a7d7c5'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-rosemary', 'rosemary', 'ローズマリー', 'Salvia rosmarinus', 'シソ科', 'ミドル', 'ハーバル、クリア、すっきり', 'シャープなハーブ感があり、作業前や朝のブレンドに向きます。柑橘やミントと相性が良い香りです。', '["作業前","朝のルーティン","クリアな印象づくり"]', '["focus","refresh"]', '["レモン","ペパーミント","ユーカリ","グレープフルーツ"]', '刺激を感じる場合があります。高濃度や長時間使用は避けてください。', '#8fb98f'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-lemon', 'lemon', 'レモン', 'Citrus limon', 'ミカン科', 'トップ', '爽やか、軽い、フレッシュ', '明るく清潔感のある柑橘の香り。集中やリフレッシュ系のトップノートとして使いやすい精油です。', '["朝の空間づくり","集中前","すっきりした印象"]', '["focus","refresh"]', '["ペパーミント","ローズマリー","ティートリー","ジュニパーベリー"]', '圧搾レモンは光毒性に注意が必要です。肌使用時は製品仕様を確認してください。', '#f0d36b'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-eucalyptus', 'eucalyptus', 'ユーカリ', 'Eucalyptus globulus', 'フトモモ科', 'トップ', 'クリア、カンファー、森林感', 'すっと抜けるような清涼感。呼吸を深くしたい気分の芳香浴やリフレッシュ系によく合います。', '["リフレッシュ","清潔感のある空間","ミント系ブレンド"]', '["refresh","focus"]', '["ペパーミント","ローズマリー","レモン","ティートリー"]', '乳幼児の顔まわりでは避けるなど、年齢や体調に応じた安全確認が必要です。', '#9fc8bd'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-tea-tree', 'tea-tree', 'ティートリー', 'Melaleuca alternifolia', 'フトモモ科', 'ミドル', 'グリーン、薬草調、清潔感', '清潔感のあるシャープな香り。単独よりも柑橘やハーブと合わせると使いやすくなります。', '["空間をすっきりさせたい時","リフレッシュ","ハーバルブレンド"]', '["refresh","focus"]', '["レモン","ユーカリ","ラベンダー","ローズマリー"]', '肌刺激を感じる場合があります。必ず希釈し、酸化した古い精油は避けてください。', '#8fbf9f'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-geranium', 'geranium', 'ゼラニウム', 'Pelargonium graveolens', 'フウロソウ科', 'ミドル', 'ローズ調、グリーン、甘い', '花らしさとグリーン感のバランスが良い香り。フローラル系をやさしく整えます。', '["気分を上げたい時","バランス感のある香り","女性らしい印象"]', '["relax","happy"]', '["ラベンダー","ベルガモット","クラリセージ","パチュリ"]', '香りが強く出やすいため少量から調整してください。', '#efb8c8'); insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-ylang-ylang', 'ylang-ylang', 'イランイラン', 'Cananga odorata', 'バンレイシ科', 'ミドル', '濃厚な花、甘い、エキゾチック', '甘く華やかで存在感のある香り。リラックス系や特別感のあるブレンドに少量加えると印象が出ます。', '["夜のリラックス","華やかさを足す","甘いフローラル"]', '["relax","happy"]', '["ベルガモット","オレンジ","サンダルウッド","ゼラニウム"]', '濃厚で頭重感を覚える場合があります。少量から使ってください。', '#e7b8c4');
